import pandas as pd
df = pd.read_csv('ban_hang.csv')
df['_d'] = pd.to_datetime(df['Ngày tháng'], errors='coerce')
def parse_vn_number(val):
    if val is None: return None
    if isinstance(val,(int,float)): return float(val)
    s=str(val).strip().replace('.','').replace(',','.')
    if s=='' or s=='.': return None
    try:
        return float(s)
    except ValueError:
        return None
